if (!savedClans) {
window.clansData = [...window.defaultPublicCategorySquads];
} else {
let mergedMap = {};
window.defaultPublicCategorySquads.forEach(s => mergedMap[s.id] = s);
savedClans.forEach(s => { if(s.id) mergedMap[s.id] = s; });
window.clansData = Object.values(mergedMap);
}

