ctx.fillStyle = 'rgba(0,0,0,0.35)'; ctx.beginPath(); ctx.arc(x + 1.5, y + 2, s * 0.34, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = window.LUDO_COLORS[o.pl.ci].c; ctx.beginPath(); ctx.arc(x, y, s * 0.34, 0, Math.PI * 2); ctx.fill();
