const lists = await Promise.all(chans.map(ch => window.loadChannelVideos(ch).catch(() => [])));
const out = [], mx = Math.max(0, ...lists.map(l => l.length));
for (let i = 0; i < mx; i++) lists.forEach(l => { if (l[i]) out.push({ ...l[i], cat: c }); });
