window.todayTrivia = function() {
const d = window.todayStr(), seed = d.split('-').reduce((a, x) => a * 31 + +x, 7), n = window.TRIVIA.length, out = [];
for (let i = 0; out.length < 3; i++) { const q = window.TRIVIA[(seed + i * 11) % n]; if (!out.includes(q)) out.push(q); }
return out.map(([q, opts, c]) => { const order = window.seededShuffle(opts.map((o, k) => k), seed + q.length); return { q, opts: order.map(k => opts[k]), correct: order.indexOf(c) }; });
};
window.dailyState = () => { try { const s = JSON.parse(localStorage.getItem('sg_daily') || '{}'); return s.d === window.todayStr() ? s : { d: window.todayStr() }; } catch (e) { return { d: window.todayStr() }; } };
