const now = new Date();
const [list] = focusId && window.predMatches.length ? [window.predMatches] : await Promise.all([window.fetchMatchesRange(new Date(now.getTime() - 86400000), new Date(now.getTime() + 7 * 86400000)), window.loadMyPicks()]);
