for (let i = 0; i < N / 2; i++) ms.push({ id: `m_${stamp || Date.now()}_${i}`, round: 1, p1: players[i * 2] || 'Open Spot', p2: players[i * 2 + 1] || 'Open Spot', s1: null, s2: null, winner: null, stage: st, streamUrl: '', mvp: null, status: 'approved' });
