l.textContent = 'Uploading…';
try { const up = await window.prepareAndUpload(f, (p) => { l.textContent = `Uploading ${p}%`; }, 1600, 1600); window._noteImg = up.url; l.textContent = '✅ Screenshot added'; } catch (e) { l.textContent = '⚠️ Upload failed'; }
