const seen = new Set();
const out = lists.flat().filter(x => { const k = (x.title || '').toLowerCase().replace(/ - [^-]+$/, '').slice(0, 60); if (!k || seen.has(k)) return false; seen.add(k); return true; })
.map(x => ({ ...x, cat })).sort((a, c) => c.date - a.date).slice(0, 90);
