const t = String(m.text || '').toLowerCase();
if (m.senderUid !== me && m.fromUid !== me && (new RegExp('@' + myTag.replace(/[.*+?^${}()|[\]\\]/g, '\\$&') + '\\b').test(t) || /(^|\s)@(all|everyone)\b/.test(t))) bubble.classList.add('sg-mention-me');
